/**
 * The second shelf of the kitchen recipe book: soups, salads, stews,
 * legumes, fish, poultry, seasonal Lithuanian dishes and more breakfasts.
 * Kept apart from `food-pantry.ts` so the book can keep growing; every
 * recipe here is checked against the combining matrix when the RECIPES
 * list is built.
 */

import type { Bi } from './food-angstrom'
import type { Meal } from './food-menu'

export type RecipeSeed = {
  id: string
  icon: string
  name: Bi
  meals: Meal[]
  minutes: number
  ingredients: { id: string; amount: Bi; optional?: boolean }[]
  steps: Bi[]
  why: Bi
}

type IngRow = [id: string, en: string, lt: string, optional?: boolean]

const B: Meal = 'breakfast'
const L: Meal = 'lunch'
const D: Meal = 'dinner'

const R = (
  id: string,
  icon: string,
  meals: Meal[],
  minutes: number,
  name: [string, string],
  ings: IngRow[],
  steps: [string, string][],
  why: [string, string],
): RecipeSeed => ({
  id,
  icon,
  meals,
  minutes,
  name: { en: name[0], lt: name[1] },
  ingredients: ings.map(([iid, en, lt, optional]) => ({ id: iid, amount: { en, lt }, optional })),
  steps: steps.map(([en, lt]) => ({ en, lt })),
  why: { en: why[0], lt: why[1] },
})

